script:
(function(){
const $ = id => document.getElementById(id);
const C = {x: 300, y: 180}, gy = 110, hy = 250, r = 36;
const rad = d => d * Math.PI / 180;
const f = n => n.toFixed(1);
// Point at a distance in a direction (degrees, counter-clockwise like in maths; SVG y points down)
const toward = (p, deg, len) => ({x: p.x + len * Math.cos(rad(deg)), y: p.y - len * Math.sin(rad(deg))});
// Point of s at height y; s goes through C with slope angle t
const onS = (y, t) => ({x: C.x + (C.y - y) / Math.tan(rad(t)), y});
function wedge(id, v, from, size){
  const a = toward(v, from, r), b = toward(v, from + size, r);
  $(id).setAttribute('d', 'M' + f(v.x) + ' ' + f(v.y) + 'L' + f(a.x) + ' ' + f(a.y) + 'A' + r + ' ' + r + ' 0 0 0 ' + f(b.x) + ' ' + f(b.y) + 'Z');
}
function place(id, p, dx, dy){ $(id).setAttribute('x', f(p.x + dx)); $(id).setAttribute('y', f(p.y + dy)); }
function label(id, v, mid){ place(id, toward(v, mid, r + 15), 0, 6); }
function update(){
  const t = +$('t').value, A = onS(gy, t), B = onS(hy, t), top = onS(20, t), bottom = onS(340, t);
  $('s').setAttribute('x1', f(top.x)); $('s').setAttribute('y1', f(top.y));
  $('s').setAttribute('x2', f(bottom.x)); $('s').setAttribute('y2', f(bottom.y));
  place('sLab', top, 10, 14);
  for (const [id, p] of [['pA', A], ['pB', B]]) { $(id).setAttribute('cx', f(p.x)); $(id).setAttribute('cy', f(p.y)); }
  place('tA', A, t < 90 ? 8 : -20, -10); place('tB', B, t < 90 ? -20 : 8, 24);
  wedge('aAlpha', A, 180, t); label('lAlpha', A, 180 + t / 2);
  wedge('aDelta', A, 180 + t, 180 - t); label('lDelta', A, 270 + t / 2);
  wedge('aBeta', B, 180, t); label('lBeta', B, 180 + t / 2);
  wedge('aGamma', B, 0, t); label('lGamma', B, t / 2);
  $('to').textContent = t + '°';
  for (const id of ['vAlpha', 'vBeta', 'vGamma']) $(id).textContent = t + '°';
  $('vDelta').textContent = (180 - t) + '°';
  $('hint').textContent = t === 90
    ? 's steht senkrecht: Alle vier Winkel sind rechte Winkel.'
    : 'α, β und γ messen alle ' + t + '°, weil g und h parallel sind. δ ergänzt α zu 180°: ' + t + '° + ' + (180 - t) + '° = 180°.';
}
$('t').addEventListener('input', update);
update();
})();
